import React, { useState } from 'react';
import ProjectCard from './components/ProjectCard';
import projects from './projects';

export default function App() {
  const [search, setSearch] = useState('');
  const [filter, setFilter] = useState('all');

  const liveCount = projects.filter(p => p.status === 'live').length;

  const filtered = projects.filter(p => {
    const matchSearch = p.name.toLowerCase().includes(search.toLowerCase());
    const matchFilter = filter === 'all' || p.status === filter;
    return matchSearch && matchFilter;
  });

  return (
    <div style={{ minHeight: '100vh', background: '#F0EEE8', padding: '2.5rem 1.25rem' }}>
      <div style={{ maxWidth: 860, margin: '0 auto' }}>

        {/* Header */}
        <div style={{ marginBottom: '2.5rem' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 12, marginBottom: 8 }}>
            <div style={{
              width: 42, height: 42, borderRadius: 12,
              background: '#1a1a18', display: 'flex', alignItems: 'center', justifyContent: 'center',
            }}>
              <i className="ti ti-layout-grid" style={{ fontSize: 20, color: '#fff' }} />
            </div>
            <h1 style={{ fontFamily: 'Syne, sans-serif', fontSize: 30, fontWeight: 800, color: '#1a1a18', letterSpacing: -0.5 }}>
              ERP Launcher
            </h1>
          </div>
          <p style={{ fontSize: 14, color: '#888', marginLeft: 54 }}>
            {projects.length} modules &nbsp;·&nbsp; {liveCount} live
          </p>
        </div>

        {/* Search + Filter bar */}
        <div style={{ display: 'flex', gap: 10, marginBottom: '1.75rem', flexWrap: 'wrap' }}>
          <div style={{ position: 'relative', flex: 1, minWidth: 180 }}>
            <i className="ti ti-search" style={{
              position: 'absolute', left: 12, top: '50%', transform: 'translateY(-50%)',
              color: '#aaa', fontSize: 16, pointerEvents: 'none',
            }} />
            <input
              value={search}
              onChange={e => setSearch(e.target.value)}
              placeholder="Search projects..."
              style={{
                width: '100%', padding: '0.6rem 0.9rem 0.6rem 2.5rem',
                borderRadius: 10, border: '0.5px solid rgba(0,0,0,0.12)',
                background: '#fff', fontSize: 14, outline: 'none', color: '#1a1a18',
              }}
            />
          </div>

          {[
            { key: 'all', label: 'All' },
            { key: 'live', label: '🟢  Live' },
            { key: 'coming_soon', label: '🟡  Coming Soon' },
          ].map(f => (
            <button key={f.key} onClick={() => setFilter(f.key)} style={{
              padding: '0.6rem 1rem', borderRadius: 10, fontSize: 13, fontWeight: 500,
              border: '0.5px solid rgba(0,0,0,0.12)', cursor: 'pointer',
              background: filter === f.key ? '#1a1a18' : '#fff',
              color: filter === f.key ? '#fff' : '#555',
              transition: 'background 0.15s, color 0.15s',
            }}>
              {f.label}
            </button>
          ))}
        </div>

        {/* Grid */}
        {filtered.length === 0 ? (
          <div style={{ textAlign: 'center', color: '#aaa', padding: '3rem', fontSize: 14 }}>
            No projects match your search.
          </div>
        ) : (
          <div style={{
            display: 'grid',
            gridTemplateColumns: 'repeat(auto-fill, minmax(210px, 1fr))',
            gap: 16,
          }}>
            {filtered.map(p => <ProjectCard key={p.id} project={p} />)}
          </div>
        )}

        {/* Footer note */}
        <p style={{ marginTop: '2.5rem', fontSize: 12, color: '#bbb', textAlign: 'center' }}>
          To add a new project, edit <code style={{ background: '#e8e6e0', padding: '1px 5px', borderRadius: 4 }}>src/projects.js</code>
        </p>

      </div>
    </div>
  );
}
